assert origin["approved_by"]=="Brett Heap in session; see review/ratification.md" and origin["approved_on"]
assert "Status: ratified" in (base/"proposal.md").read_text()
assert "Ratified:" in (base/"review/ratification.md").read_text()
assert permission["decision"]=="accepted" and permission["owner"]=="Brett Heap" and permission["mode"]=="source"
assert permission["proposal_sha256"]==hashlib.sha256((base/"proposal.md").read_bytes()).hexdigest()
assert permission["latest_consumed_choice"]["at"]=="2026-11-14T16:57:52.719Z"
assert permission["latest_consumed_choice"]["raw_record_sha256"]=="fb7c79ad567ff3cd440a3cd4cb4f0d1d58ffbef3af327d9e5504964d5e483249"
accepted=(base/"review/support-scope-acceptance.md").read_text()
for value in ("Approve these qualification candidates (Recommended)","v0.29.7","v1.104.7","Ubuntu 24.04","29.9.3","Windows 11","macOS 15","Standalone GUI PKG","Debian"):
 assert value in accepted, value
tasks={}
for line in Path("specs/043-private-connectivity-production/tasks.md").read_text().splitlines():
 if line.startswith(("- [ ] T02","- [x] T02")):
  task=line[6:10]
  if task in ("T020","T021","T022","T023"):
   _,separator,tail=line.partition(" — files: ")
   assert separator
   files,separator,_=tail.partition(" — verify:")
   assert separator
   tasks[task]={"owner":"L" if "(Owner=L;" in line else "other","files":re.findall(chr(96)+"([^"+chr(96)+"]+)"+chr(96),files)}
assert permission["definition_sha256"]=="66db63ec98e366f141230d22e6e4e159916bb997f159916159dcc7b6ae3f32d0"
declared={}
for line in (base/"design.md").read_text().splitlines():
 if re.match(r"\| T02[0-3] \|",line):
  cells=line.split("|");declared[cells[1].strip()]=cells[2].strip().split("<br>")
assert set(declared)==set(permission["per_task_source_scope"])=={"T020","T021","T022","T023"}
for task,files in declared.items():
 assert tasks[task]["owner"]=="L" and files==tasks[task]["files"]==permission["per_task_source_scope"][task]
matrix=permission["matrix"]
assert matrix=={"headscale":"0.29.7","tailscale":"1.104.7","server":{"os":"Ubuntu 24.04 LTS","architecture":"amd64","docker_engine":"29.9.3"},"clients":[{"os":"Windows 11","architecture":"amd64","channel":"official MSI"},{"os":"macOS 15","architecture":"Apple Silicon","channel":"official Standalone GUI PKG"},{"os":"macOS 15","architecture":"Intel","channel":"official Standalone GUI PKG"},{"os":"Ubuntu 24.04 LTS","architecture":"amd64","channel":"official Debian package/repository"}],"qualified":False}
ratification=(base/"review/ratification.md").read_text()
for value in ("Brett Heap","Project lifetime","Existing owner-repository permissions","review of actual output/provenance","no new export directory"):
 assert value in ratification, value
assert permission["custody_process"]["retention"]=="project lifetime"
assert permission["source_limits"]=={"target_effects":False,"cloud_spend_usd":0,"runner_dispatch":False,"installation":False,"enrollment":False,"fault_injection":False}
assert len(permission["later_required_inputs"])==4
assert all(permission["boundaries"][k] is False for k in ("allocates_version","advances_pins","authorizes_tag","authorizes_target_effects"))
subprocess.run(["python3","scripts/validate-openspec-cli-pin.py","--change","commission-headscale-production","--strict"],check=True)
facts={
 "package-owner-scope":{"owner":permission["owner"],"roles":permission["roles"],"origin_approved":True,"ratified":True,"proposal_sha256":permission["proposal_sha256"],"accepted_task_scopes":declared,"definition_sha256":permission["definition_sha256"]},
 "local-platform-support":{"matrix":matrix,"actual_choice_at":permission["latest_consumed_choice"]["at"],"raw_record_sha256":permission["latest_consumed_choice"]["raw_record_sha256"],"compatibility_qualified":False},
 "consumed-decisions":{"source_custody":permission["custody_process"],"source_limits":permission["source_limits"],"later_required_inputs":permission["later_required_inputs"],"live_authority_granted":False}
}
print("L_ACCEPTANCE_FACTS="+json.dumps(facts,sort_keys=True))
'

